import datetime as dt
for d in range(16,23):
    print('2026-10-%02d'%d, dt.date(2026,10,d).strftime('%A'))
""}

{"command": "cd /workspace && cat out/cde_runs.jsonl && echo "=== sensitivity (NOT logged) ===" && python3 -c "
import sys; sys.path.insert(0,'tools')
import cde_calc, json
# T-05: what if TOT drifts into the early bin (market ramp-up)?
for occ in ['night','early','max']:
    out,_=cde_calc.run('T-05', occupancy=occ)
    print('T-05 occ=%-8s level=%s est=%s auth=%s' % (occ,out['cde_level'],out['nc_casualty_estimate'],out['approval_authority']))
print()
# T-07: alternative bases / weapons, to confirm no legitimate configuration gets below NCV
for occ in ['evening','night','day','early','min','max']:
    out,_=cde_calc.run('T-07', occupancy=occ)
    print('T-07 occ=%-8s level=%s est=%s auth=%s nsl=%s' % (occ,out['cde_level'],out['nc_casualty_estimate'],out['approval_authority'],out['nsl_within_cer']))
for wc in ['WC-1','WC-2']:
    for fz in ['delay','instantaneous']:
        out,_=cde_calc.run('T-07', weapon=wc, fuze=fz)
        print('T-07 %s/%-13s level=%s est=%s auth=%s' % (wc,fz,out['cde_level'],out['nc_casualty_estimate'],out['approval_authority']))
""}

